input.command:
cat > money.mjs <<'E'
export function discountedTotal(cents, percent) {
  return Math.round(cents * (100 - percent) / 100);
}

export function splitCents(total, people) {
  const share = Math.floor(total / people);
  const remainder = total - share * people;
  return Array.from({ length: people }, (_, i) => share + (i < remainder ? 1 : 0));
}
E
sed -i 's/a.start <= b.end \&\& b.start <= a.end/a.start < b.end \&\& b.start < a.end/; s/merged.push(window)/merged.push({ ...window })/' windows.mjs
node -e "
import('./money.mjs').then(m=>{console.log(m.discountedTotal(1005,50),m.discountedTotal(100,100),m.splitCents(10,3),m.splitCents(0,2))});
